    35|function normalizePrompt(prompt: string): string {
    36|  return prompt.trim().toLowerCase().replace(/\s+/g, ' ');
    37|}
    38|
    39|/**
    40| * Deterministic exact-echo command detector (acceptance test B).
    41| *
    42| * When the owner sends an explicit "reply/respond/say exactly: <X>" instruction,
    43| * IVX must return <X> VERBATIM — proving the LATEST owner message is the one being
    44| * executed, with no LLM paraphrasing, no clarification hijack, and no truncation.
    45| * Returns the exact text to echo (preserving original casing/characters), or null.
    46| */
    47|export function resolveExactEchoCommand(prompt: string): string | null {
    48|  const raw = prompt.trim();
    49|  if (!raw) {
    50|    return null;
    51|  }
    52|  // Match: reply/respond/answer/say/repeat/echo [back] exactly [with][:] <payload>
    53|  const match = raw.match(/^(?:please\s+)?(?:reply|respond|answer|say|repeat|echo|output|return|print)\s+(?:back\s+)?exactly(?:\s+with)?\s*[:\-]?\s*([\s\S]+)$/i);
    54|  if (!match) {
    55|    return null;
    56|  }
    57|  let payload = match[1].trim();
    58|  // Strip a single pair of wrapping quotes the owner may have added around the payload.
    59|  const quoted = payload.match(/^(["'\u201c\u2018])([\s\S]+)(["'\u201d\u2019])$/);
    60|  if (quoted) {
    61|    payload = quoted[2].trim();
    62|  }
    63|  return payload.length > 0 ? payload : null;
    64|}
    65|
    66|/**
    67| * Diagnostic-intent guard — mirrors the client-side ivxOwnerIntentClassifier.
    68| *
    69| * A prompt that starts with or leads with a diagnostic question
    70| * ("audit the loading problem...", "why is the chat...", "explain what is wrong")
    71| * must NEVER be routed to the senior developer worker, even if it ends with
    72| * "deploy it" / "fix it" / "and ship it". The owner's reported bug was exactly
    73| * this: "Audit the loading problem on this chat, explain what is wrong, what
    74| * must be fixed, and deploy it" matched the deploy/fix execution signals and
    75| * was misrouted to the worker, which returned progress percentages instead of
    76| * a real diagnosis. Diagnostic intent takes PRIORITY over execution intent.
    77| */
    78|function isDiagnosticLeadingIntent(normalized: string): boolean {
    79|  // Leading diagnostic verbs: the prompt opens with an audit/diagnosis/explain request.
    80|  // We only match at the start of the prompt (first ~120 chars) so a later
    81|  // "...and audit the result" clause inside a long build task does not hijack it.
    82|  const head = normalized.slice(0, 160);
    83|  const leadsWithDiagnostic = /^(?:please\s+)?(?:audit|diagnose|diagnosis|diagnostic|explain|why\s+is|why\s+does|why\s+doesn't|what\s+is\s+wrong|what's\s+wrong|what\s+is\s+broken|what's\s+broken|investigate|trace|root\s+cause|figure\s+out\s+why|tell\s+me\s+why|tell\s+me\s+what\s+is\s+wrong|tell\s+me\s+what's\s+wrong)\b/i.test(head);
    84|  if (leadsWithDiagnostic) {
    85|    return true;
    86|  }
    87|  // Explicit diagnostic phrasing anywhere in the prompt that pairs an inspection
    88|  // verb with a "loading / broken / wrong / failing" symptom and an explanation ask.
    89|  const hasInspectionVerb = /\b(audit|diagnose|diagnosis|diagnostic|investigate|trace|root\s+cause|figure\s+out)\b/i.test(normalized);
    90|  const hasSymptom = /\b(loading|load\s+problem|blank|frozen|spinner|slow|stuck|broken|wrong|failing|crash|hangs?|won't\s+load|doesn't\s+load|not\s+loading)\b/i.test(normalized);
    91|  const asksForExplanation = /\b(explain|tell\s+me|what\s+is\s+wrong|what's\s+wrong|why\s+is|why\s+does|root\s+cause)\b/i.test(normalized);
    92|  return hasInspectionVerb && hasSymptom && asksForExplanation;
    93|}
    94|
    95|/**
    96| * Detects a long, structured owner EXECUTION command or task block (e.g.
    97| * "BLOCK 28 Visitor-to-Investor Conversion Engine / Create: ... / Track: ...").
    98| *
    99| * These must NEVER be hijacked by short clarification intents (physical location,
   100| * time, manual-answer, infrastructure-runtime) just because the spec happens to
   101| * mention a keyword like "location", "backend", or "runtime" inside a much larger
   102| * instruction. The whole class of "IVX answered the wrong context" bugs comes from
   103| * a clarification regex matching a single word inside a long command and short-
   104| * circuiting before execution routing. When this returns true, the planner routes
   105| * the command to task decomposition and the handler skips every clarification gate.
   106| */
   107|export function isOwnerExecutionOrTaskBlock(prompt: string): boolean {
   108|  const raw = prompt.trim();
   109|  if (!raw) {
   110|    return false;
   111|  }
   112|  const normalized = normalizePrompt(prompt);
   113|
   114|  // DIAGNOSTIC PRIORITY: a prompt that leads with an audit/diagnose/explain request
   115|  // must never be treated as an execution/task block, even if it contains deploy/fix/commit
   116|  // signals later. The owner's "Audit the loading problem... and deploy it" was misrouted
   117|  // here, returning worker progress instead of a real diagnosis. This guard runs FIRST.
   118|  if (isDiagnosticLeadingIntent(normalized)) {
   119|    return false;
   120|  }
   121|
   122|  // Explicit "BLOCK N" / "STEP N" / "PHASE N" task headers are always task blocks.
   123|  if (/\b(block|step|phase)\s*\d+\b/.test(normalized)) {
   124|    return true;
   125|  }
   126|
   127|  // Structured spec markers the owner uses for feature/task blocks.
   128|  const specMarkerCount = (raw.match(/^\s*(create|track|stages?|capabilities|dashboard|requirements?|safety|store|return|show|build|objective|audit|capabilities?|metrics?)\s*:/gim) ?? []).length;
   129|  if (specMarkerCount >= 2) {
   130|    return true;
   131|  }
   132|
   133|  // Multi-line, sufficiently long instructions are treated as task blocks so a
   134|  // single keyword can never reroute them to a one-line clarification answer.
   135|  const lineCount = raw.split(/\n/).filter((line) => line.trim().length > 0).length;
   136|  if (raw.length >= 320 && lineCount >= 4) {
   137|    return true;
   138|  }
   139|
   140|  // Imperative engine/system/feature build commands ("... Conversion Engine",
   141|  // "build the ... system") that are also reasonably long.
   142|  if (raw.length >= 90 && /\b(engine|system|pipeline|module|platform|dashboard|workflow)\b/.test(normalized) && /\b(create|build|implement|add|wire|ship|deploy|design|develop)\b/.test(normalized)) {
   143|    return true;
   144|  }
   145|
   146|  // Production-execution signals — explicit owner commands to commit/push/deploy/
   147|  // verify on this system. These must NEVER be hijacked by short-circuit
   148|  // clarification gates (time/date, location, manual-answer) just because the
   149|  // prompt happens to contain a date phrase like "(today's date)" inside a larger
   150|  // deploy instruction. This closes the chat→worker narrative-only fallback gap:
   151|  // a prompt like "Bump the version marker to ...-2026-07-19 (today's date), commit
   152|  // to GitHub, deploy to Render, verify /health" must route to the developer
   153|  // executor, not return "The answer is 2019." as a math/time query.
   154|  const hasCommitSignal = /\b(commit|push\s+(?:to\s+)?github|github\s+main|pr\s*#\d)\b/.test(normalized);
   155|  const hasDeploySignal = /\b(deploy|render|trigger\s+a\s+deploy|live\s+commit|production\s+commit)\b/.test(normalized);
   156|  const hasVerifySignal = /\b(verify|verified\s+evidence|verify\s+the\s+live|live\s+runtime\s+commit|github\s+head|sha\s+match|\/health)\b/.test(normalized);
   157|  const hasMutationSignal = /\b(bump|update|change|edit|modify|patch|fix|migrate|rollback)\b/.test(normalized)
   158|    && /\b(version|marker|file|endpoint|route|table|policy|config|code|production)\b/.test(normalized);
   159|  const executionSignalCount = [hasCommitSignal, hasDeploySignal, hasVerifySignal, hasMutationSignal].filter(Boolean).length;
   160|  if (executionSignalCount >= 2) {
   161|    return true;
   162|  }
   163|
   164|  // App-scaffold / new-app-from-scratch signals — explicit owner commands to
   165|  // CREATE a new app, scaffold a new project, build a new module from scratch,
   166|  // or run a stress/load test. These are real code-production requests the
   167|  // senior developer worker handles (create_file patch operations), NOT
   168|  // planning/narrative prompts. Without this guard, the planner mis-routes
   169|  // them to app_build_planning → gpt_conversation (narrative GPT-4o answer)
   170|  // and the senior developer never runs. Closes the PARTIAL item gap where
   171|  // "create a new app from scratch" returned a narrative plan instead of
   172|  // real scaffolded files.
   173|  const hasAppScaffoldSignal = /\b(?:create|scaffold|build|generate)\s+(?:a\s+)?(?:new\s+)?(?:app|application|module|service)\s+(?:from\s+scratch|project|skeleton|shell|template|called\s+|named\s+)/i.test(normalized)
   174|    || /\bnew\s+app\s+from\s+scratch/i.test(normalized)
   175|    || /\bscaffold\s+(?:a\s+)?(?:new\s+)?(?:app|project|module)/i.test(normalized);
   176|  const hasStressTestSignal = /\bstress\s*test/i.test(normalized)
   177|    || /\bload\s*test/i.test(normalized)
   178|    || /\brun\s+a\s+(?:stress|load)\s+test/i.test(normalized);
   179|  if (hasAppScaffoldSignal || hasStressTestSignal || isServerBugFixRequest(normalized) || asksToCreateAndShowProof(normalized)) {
   180|    return true;
   181|  }
